param([string]$SourceVersion='0.1.7',[string]$CandidateVersion='0.1.8')
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
$stamp=(Get-Date).ToString('yyyyMMddTHHmmssfff');$run=Join-Path $root ('reports/staged-program-interrupt-'+$stamp)
$source=Join-Path $root 'reports/p6-windows-package-017-20261012';$candidate=Join-Path $root 'reports/p6-windows-package-018-20261012'
$install=Join-Path $run 'installed app';$data=Join-Path $run 'data';$project=Join-Path $run 'project';$tx=Join-Path $run 'transaction'
$tool=Join-Path $PSScriptRoot 'manage-windows-update.ps1';$core=Join-Path $install 'cerulean-runtime.exe';$calls=@();$prepare=$null;$child=$null;$failure=$null;$hold=$null
function H([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function Save([string]$p,$v){$json=($v|ConvertTo-Json -Depth 30);[IO.File]::WriteAllText([string]$p,[string]$json,[Text.UTF8Encoding]::new($false))}
function C([string[]]$a){$raw=& $core --workbench --data-dir $data @a 2>&1;$code=$LASTEXITCODE;if($code){throw "core failed $code"};(($raw -join "`n")|ConvertFrom-Json)}
function Inv([string]$p){@(Get-ChildItem -LiteralPath $p -File -Recurse -Force | Sort-Object FullName | ForEach-Object {@{path=$_.FullName.Substring($p.Length);bytes=$_.Length;sha256=(H $_.FullName)}})}
try{
 foreach($d in @($source,$candidate)){if(-not (Test-Path (Join-Path $d 'manifest.json'))){throw "Missing frozen package $d"}}
 foreach($key in @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\CeruleanLonging','HKCU:\Software\ceruleanlonging\CeruleanLonging')){if(Test-Path $key){throw 'Existing user installation; do not modify it'}}
 New-Item -ItemType Directory -Path $run,$project | Out-Null
 $installer=Join-Path $source 'setup.exe';$p=Start-Process $installer -ArgumentList @('/S','/NS',"/D=$install") -WindowStyle Hidden -PassThru;if(-not $p.WaitForExit(120000)){throw 'Installer timeout'};if($p.ExitCode){throw "Installer failed $($p.ExitCode)"};$p.Dispose()
 $null=C @('service','start');$null=C @('project','add','--id','staging-20261013','--root',$project,'--timezone','Asia/Shanghai');$beforeProject=(C @('project','show','--project','staging-20261013')).result.workflow|ConvertTo-Json -Depth 30 -Compress
 $review=C @('upgrade','review','--source-package',$source,'--source-manifest-sha256',(H (Join-Path $source 'manifest.json')),'--candidate-package',$candidate,'--candidate-manifest-sha256',(H (Join-Path $candidate 'manifest.json')));$hold=(C @('upgrade','prepare','--review-digest',$review.result.upgradeReview.digest)).upgradeHold.holdDigest;$null=C @('service','stop')
 $fixture=Join-Path $install 'STAGING-FIXTURE-256MiB.bin';$fs=[IO.File]::Open($fixture,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$fs.SetLength(268435456);$fs.Flush($true)}finally{$fs.Dispose()}
 $programBefore=Inv $install;$dataBefore=Inv $data;Save (Join-Path $run 'original-program.json') $programBefore;Save (Join-Path $run 'original-data.json') $dataBefore
 $args=@('-NoProfile','-ExecutionPolicy','RemoteSigned','-File',('"'+$tool+'"'),'-Action','Prepare','-TransactionDirectory',('"'+$tx+'"'),'-InstalledDirectory',('"'+$install+'"'),'-DataDirectory',('"'+$data+'"'),'-HoldDigest',$hold,'-SourcePackage',('"'+$source+'"'),'-SourceManifestSha256',(H (Join-Path $source 'manifest.json')),'-CandidatePackage',('"'+$candidate+'"'),'-CandidateManifestSha256',(H (Join-Path $candidate 'manifest.json')),'-AllowUnsignedInternal')
 $si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe';$si.Arguments=$args -join ' ';$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
 $child=[Diagnostics.Process]::Start($si);$handle=$child.Handle;Save (Join-Path $run 'owned-prepare-process.json') @{pid=$child.Id;handleCaptured=($handle -ne [IntPtr]::Zero);transaction=$tx;parentPid=$PID;mode='staged-program-copy'}
 $stagedRuntime=Join-Path $tx 'staged-program\cerulean-runtime.exe';$stagedFixture=Join-Path $tx 'staged-program\STAGING-FIXTURE-256MiB.bin';$seen=$false;$samples=@();$deadline=[DateTime]::UtcNow.AddMinutes(3)
 while([DateTime]::UtcNow -lt $deadline -and -not $child.HasExited){if(Test-Path $stagedRuntime){$seen=$true;$items=@($stagedRuntime,$stagedFixture)|Where-Object {Test-Path $_};$samples+=@($items|ForEach-Object {@{path=$_.Substring($tx.Length);bytes=(Get-Item $_).Length;at=[DateTimeOffset]::Now.ToString('o')}});if($items.Count -and (($items|ForEach-Object {(Get-Item $_).Length}|Measure-Object -Sum).Sum -gt 0)){break}};Start-Sleep -Milliseconds 25}
 if(-not $seen){throw 'staged-program copy was not observed before Prepare exit'}
 $child.Refresh();$alive=-not $child.HasExited;$child.Kill();$wait=$child.WaitForExit(30000);$stdout=$child.StandardOutput.ReadToEnd();$stderr=$child.StandardError.ReadToEnd();$exit=$child.ExitCode;Save (Join-Path $run 'staged-observation.json') @{observed=$seen;samples=$samples;pid=$child.Id;wasAlive=$alive;hasExited=$wait;exit=$exit;stdout=$stdout;stderr=$stderr;terminatedAt=[DateTimeOffset]::Now.ToString('o')}
 if(-not $wait -or -not $alive){throw 'Original Prepare termination not confirmed'}
 $events=@(Get-ChildItem $tx -Filter 'event-*.json' -ErrorAction SilentlyContinue);$plan=Test-Path (Join-Path $tx 'plan.json');$manifest=Test-Path (Join-Path $tx 'data-backup\manifest.json');$partial=(Test-Path $stagedRuntime)
 $result=[ordered]@{status='passed';run=$run;scenario='017-to-018-prepare-staged-program-copy-controller-termination';sourcePackage=$source;candidatePackage=$candidate;frozenTools='scripts/manage-windows-update.ps1';prepareAttempts=1;stagedProgramObserved=$seen;stagedSamples=$samples;originalPreparePid=$child.Id;originalPrepareWasAlive=$alive;originalPrepareWaited=$wait;originalPrepareExit=$exit;dataBackupManifestPublished=$manifest;planPublished=$plan;preparedEventPublished=([bool]$events.Count);stagedProgramResidual=$partial;backupVerify='not-run-because-termination-before-plan';originalProgramUnchanged=($programBefore|ConvertTo-Json -Compress -Depth 10 -eq (Inv $install|ConvertTo-Json -Compress -Depth 10));originalDataUnchanged=($dataBefore|ConvertTo-Json -Compress -Depth 10 -eq (Inv $data|ConvertTo-Json -Compress -Depth 10));abandon='not-run-driver-preserves-real-termination-evidence';cleanup='preserved-for-inspection';calls=@(@{action='upgrade.review'},@{action='upgrade.prepare'},@{action='Prepare';pid=$child.Id})}
 Save (Join-Path $run 'result.json') $result; $result|ConvertTo-Json -Depth 30 -Compress
}catch{$failure=$_;$result=[ordered]@{status='failed';run=$run;scenario='017-to-018-prepare-staged-program-copy-controller-termination';message=$_.Exception.Message;cleanup='preserved-for-inspection';failureEvidence=$true};Save (Join-Path $run 'result.json') $result;$result|ConvertTo-Json -Depth 20 -Compress;exit 1}
